import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第一册：英语初阶 · Lesson 3 Sorry, sir.","description":"学习 be 动词的否定和缩写，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 3 Sorry, sir.","description":"学习 be 动词的否定和缩写，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 be 动词的否定和缩写，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 2 Is this your ...?","link":"/life/english/new-concept/book-1/unit-01/lesson-002"},"next":{"text":"第一册：英语初阶 · Lesson 4 Is this your ...?","link":"/life/english/new-concept/book-1/unit-01/lesson-004"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 2 Is this your ...?","link":"/life/english/new-concept/book-1/unit-01/lesson-002"},"next":{"text":"第一册：英语初阶 · Lesson 4 Is this your ...?","link":"/life/english/new-concept/book-1/unit-01/lesson-004"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-01/lesson-003.md","filePath":"life/english/new-concept/book-1/unit-01/lesson-003.md"}'),i={name:"life/english/new-concept/book-1/unit-01/lesson-003.md"};function s(r,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-lesson-3-sorry-sir" tabindex="-1">第一册：英语初阶 · Lesson 3 Sorry, sir. <a class="header-anchor" href="#第一册-英语初阶-·-lesson-3-sorry-sir" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 3 Sorry, sir.&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-01/overview">单元 1</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-004">配套课 Lesson 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>发现认错物品后否认并道歉 本课要掌握be 动词的否定和缩写，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。先根据情境判断为什么要这样问或这样说，再看语言形式。</p><p>本课为情景学习；完成后进入相邻偶数课进行句型迁移。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>sorry</td><td>/ˈsɒri/</td><td>adj.</td><td>抱歉的</td><td>be sorry</td></tr><tr><td>coat</td><td>/kəʊt/</td><td>n.</td><td>外套</td><td>a winter coat</td></tr><tr><td>umbrella</td><td>/ʌmˈbrelə/</td><td>n.</td><td>伞</td><td>my umbrella</td></tr><tr><td>not</td><td>/nɒt/</td><td>adv.</td><td>不</td><td>is not</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>is not — 否定身份或归属</li><li>my coat — 名词前说明所属</li></ul><h2 id="语法讲解-be-动词的否定和缩写" tabindex="-1">语法讲解：be 动词的否定和缩写 <a class="header-anchor" href="#语法讲解-be-动词的否定和缩写" aria-label="Permalink to &quot;语法讲解：be 动词的否定和缩写&quot;">​</a></h2><p>否定句在 be 后加 not。is not 可缩为 isn&#39;t；this is 的主语指单数物品。否定回答应先表明不是，再补充正确归属。my、your 后必须接名词；不能把否定词放在名词前来替代谓语否定。sorry 用于表达歉意，excuse me 多用于打扰前引起注意，语境不同。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>This is not my umbrella.</p></blockquote><p>这不是我的伞。</p><p>This 是主语，is 是系动词，not 否定整项归属，my umbrella 是表语；my 后保留名词 umbrella。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>不要用 This not my ...；英语完整陈述句通常仍需 be。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“This is not my umbrella.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>This is not my umbrella. That is not your coat.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“发现认错物品后否认并道歉”写两至三句，再读给同伴听。至少使用一次be 动词的否定和缩写，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>This 是主语，is 是系动词，not 否定整项归属，my umbrella 是表语；my 后保留名词 umbrella。 That 指稍远的单数物品；is not 是系表结构的否定，your coat 说明被否定的所属关系。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>补全否定句：This ___ not my umbrella.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> is</p><p><strong>解析：</strong> 按本课规则判断：否定句在 be 后加 not。is not 可缩为 isn&#39;t；this is 的主语指单数物品。否定回答应先表明不是，再补充正确归属。my、your 后必须接名词；不能把否定词放在名词前来替代谓语否定。sorry 用于表达歉意，excuse me 多用于打扰前引起注意，语境不同。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“这不是我的伞。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> This is not my umbrella.</p><p><strong>解析：</strong> This 是主语，is 是系动词，not 否定整项归属，my umbrella 是表语；my 后保留名词 umbrella。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：That is not your coat.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 那不是你的外套。</p><p><strong>解析：</strong> That 指稍远的单数物品；is not 是系表结构的否定，your coat 说明被否定的所属关系。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：be 动词的否定和缩写。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-002">上一课</a> · <a href="/life/english/new-concept/book-1/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-004">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(i,[["render",s]]);export{p as __pageData,b as default};
